<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
class ExpenseDemoSeeder extends Seeder{
 public function run():void{$company=DB::table('companies')->where('status','active')->first();if(!$company)return;$branch=DB::table('branches')->where(['company_id'=>$company->id,'status'=>'active'])->first();$user=DB::table('users')->where(['company_id'=>$company->id,'status'=>'active'])->first();if(!$branch||!$user)return;
  foreach([['Internet empresarial','Servicios','Plan mensual de Internet',189.90,10,'transfer'],['Alquiler del local','Alquiler','Alquiler mensual del local comercial',1800,5,'transfer']]as$x)DB::table('recurring_expenses')->updateOrInsert(['company_id'=>$company->id,'branch_id'=>$branch->id,'name'=>$x[0]],['category'=>$x[1],'description'=>$x[2],'usual_amount'=>$x[3],'due_day'=>$x[4],'starts_on'=>now()->startOfYear()->toDateString(),'usual_payment_method'=>$x[5],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);
  foreach([['Luz del local','electricity','kWh','LUZ-PIU-01',428.60,8450.300],['Agua del local','water','m³','AGUA-PIU-01',116.40,1270.500]]as$x){$meter=DB::table('utility_meters')->where(['company_id'=>$company->id,'branch_id'=>$branch->id,'name'=>$x[0]])->first();if(!$meter){$id=DB::table('utility_meters')->insertGetId(['company_id'=>$company->id,'branch_id'=>$branch->id,'name'=>$x[0],'type'=>$x[1],'unit'=>$x[2],'identifier'=>$x[3],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);$meter=(object)['id'=>$id];}$date=now()->startOfMonth()->addDays(7)->toDateString();$reading=DB::table('meter_readings')->where(['utility_meter_id'=>$meter->id,'reading_date'=>$date])->first();if(!$reading){$id=DB::table('meter_readings')->insertGetId(['utility_meter_id'=>$meter->id,'user_id'=>$user->id,'reading_date'=>$date,'value'=>$x[5],'consumption'=>$x[5],'amount'=>$x[4],'created_at'=>now(),'updated_at'=>now()]);$reading=(object)['id'=>$id];}DB::table('expenses')->insertOrIgnore(['company_id'=>$company->id,'branch_id'=>$branch->id,'user_id'=>$user->id,'category'=>'Servicios','description'=>$x[0].' · recibo '.$date,'expense_type'=>'variable_metered','amount'=>$x[4],'financial_status'=>'pending','expense_date'=>$date,'period'=>now()->format('Y-m'),'due_date'=>$date,'meter_reading_id'=>$reading->id,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);}
  foreach(DB::table('recurring_expenses')->where(['company_id'=>$company->id,'branch_id'=>$branch->id,'status'=>'active'])->get()as$t)DB::table('expenses')->insertOrIgnore(['company_id'=>$company->id,'branch_id'=>$branch->id,'user_id'=>$user->id,'category'=>$t->category,'description'=>$t->description,'expense_type'=>'fixed','amount'=>$t->usual_amount,'financial_status'=>'pending','expense_date'=>now()->startOfMonth()->toDateString(),'period'=>now()->format('Y-m'),'due_date'=>now()->startOfMonth()->day($t->due_day)->toDateString(),'payment_method'=>$t->usual_payment_method,'recurring_expense_id'=>$t->id,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);
 }
}
